<template>
  <aside class="reasoning-panel" aria-label="分析过程面板">
    <header class="inspector-header"><div><span class="inspector-kicker">执行与证据</span><h3>分析过程</h3></div><button class="icon-button" aria-label="收起分析过程" @click="$emit('close')">×</button></header>
    <section class="mission-status" :class="outcome.status" role="status" aria-live="polite">
      <div class="mission-label"><span class="status-beacon"></span><strong>{{ outcome.label }}</strong><time v-if="elapsed">{{ elapsed }}</time></div>
      <p>{{ latestAnalysisSummary(workflow) || outcome.description }}</p>
      <div class="mission-facts"><span>{{ stageNodes.length }} 个已记录步骤</span><span v-if="hasRows">{{ rowCount }} 行查询结果</span><span v-if="workflow.retry_count">修复 {{ workflow.retry_count }} 次</span></div>
    </section>
    <nav class="inspector-tabs" aria-label="分析过程视图"><button v-for="item in tabs" :key="item.id" :aria-pressed="tab===item.id" @click="tab=item.id">{{ item.label }}<span v-if="item.id==='diagnostics' && issues.length">{{ issues.length }}</span></button></nav>
    <div class="inspector-body">
      <section v-if="tab==='progress'" class="progress-view">
        <AnalysisBrief :workflow="workflow" :result="result" :busy="outcome.status==='running'" compact />
        <div class="section-caption"><span>本轮分析路径</span><button :aria-pressed="follow" @click="follow=!follow">{{ follow?'跟随当前步骤 ✓':'跟随当前步骤' }}</button></div>
        <ol class="phase-rail"><li v-for="phase in phases" :key="phase.id" :class="[phase.status,{selected:selectedPhase===phase.id}]">
          <button class="phase-pick" :aria-pressed="selectedPhase===phase.id" @click="selectPhase(phase.id)"><span class="phase-symbol">{{ phase.status==='completed'?'✓':phase.status==='running'?'◌':phase.status==='warning'?'!':String(phase.id+1).padStart(2,'0') }}</span><span><strong>{{ phase.title }}</strong><small>{{ phase.nodes.length ? `${phase.nodes.length} 个实际步骤 · ${nodeLabel(phase.status)}` : '尚未收到执行记录' }}</small></span><span class="phase-chevron">›</span></button>
        </li></ol>
        <section class="phase-detail" aria-label="所选阶段详情"><div class="detail-heading"><h4>{{ phases[selectedPhase]?.title }}</h4><span>{{ nodeLabel(phases[selectedPhase]?.status) }}</span></div><p>{{ phases[selectedPhase]?.description }}</p>
          <div v-if="!phases[selectedPhase]?.nodes.length" class="inspector-empty">该阶段尚未收到真实执行记录。</div>
          <details v-for="node in phases[selectedPhase]?.nodes || []" :key="node.key" class="step-detail" :open="['failed','warning','interrupted','retrying','running'].includes(node.status)">
            <summary><span class="mini-status" :class="node.status">{{ nodeMark(node.status) }}</span><strong>{{ node.title }}</strong><small>{{ nodeLabel(node.status) }}</small></summary>
            <div class="step-copy"><span>{{ node.role || '领域专家' }}<template v-if="node.skill"> · {{ node.skill }}</template></span><p v-if="node.summary && node.summary!==node.title">{{ node.summary }}</p><span v-if="node.attempts>1">{{ node.attempts }} 次执行记录已合并</span><p v-if="node.status==='interrupted'">本轮已结束，此步骤没有收到成功确认。</p></div>
          </details>
        </section>
        <div v-if="!stageNodes.length" class="inspector-empty">连接建立后会同步真实步骤，不预填完成状态。</div>
        <button v-if="['failed','partial'].includes(outcome.status) && allowRetry" class="retry-action" @click="$emit('retry')">把原问题带回输入框 ↗</button>
      </section>
      <section v-else-if="tab==='queries'" class="query-view">
        <div class="section-caption"><span>本次查询依据</span><small>只展示已生成的查询</small></div>
        <label v-if="datasets.length>1" class="query-source">结果来源<select v-model="selectedDataset"><option v-for="(ds,index) in datasets" :key="index" :value="index">{{ ds.dataset_name || `结果 ${index+1}` }}</option></select></label>
        <section v-if="currentDataset" class="query-evidence"><div class="query-meta"><strong>{{ currentDataset.dataset_name || '授权数据集' }}</strong><span>{{ currentDataset.rows?.length || 0 }} 行结果</span></div><p>组织范围由服务端授权策略控制；下列为本轮实际查询。</p><pre v-if="currentDataset.sql" class="inspector-sql">{{ currentDataset.sql }}</pre><p v-else class="inspector-empty">本结果尚无可展示的 SQL。</p><details v-if="currentDataset.agent3_review?.review_summary" class="review-note"><summary>审核结论</summary><p>{{ currentDataset.agent3_review.review_summary }}</p></details></section>
        <template v-else-if="queryLogs.length"><label class="query-source">执行中的查询<select v-model="selectedQueryLog"><option v-for="(log,index) in queryLogs" :key="log.key || index" :value="index">{{ log.title }}</option></select></label><slot name="content" :log="queryLogs[selectedQueryLog]" :index="selectedQueryLog"></slot></template>
        <div v-else class="inspector-empty">尚未生成可展示的 SQL。查询失败不等同于业务数据为空。</div>
      </section>
      <section v-else-if="tab==='report' && allowReport" class="report-preview"><div class="section-caption"><span>HTML 分析报告</span><button type="button" @click="$emit('view-report')">放大阅读 ↗</button></div><iframe title="本轮 HTML 分析报告" sandbox="" :srcdoc="reportHtml"></iframe></section>
      <section v-else class="diagnostics-view">
        <div class="diagnostic-notice" :class="outcome.status"><strong>{{ issues.length ? '需要关注的步骤' : '本轮诊断记录' }}</strong><p>{{ issues.length?'修复过的步骤会合并为一个节点；未确认成功的步骤不会显示绿勾。':'当前没有记录到未解决的步骤异常。' }}</p></div>
        <div v-for="node in issues" :key="node.key" class="issue-card"><span>{{ nodeLabel(node.status) }}</span><h4>{{ node.title }}</h4><p>{{ node.summary || '请核对该步骤的查询与审核依据。' }}</p><button @click="tab='progress';selectPhase(phases.find(p=>p.nodes.some(n=>n.key===node.key))?.id || 0)">定位到该步骤 ↗</button></div>
        <details class="technical-records"><summary>技术事件 · {{ logs.length }} 条</summary><div v-for="(log,index) in logs" :key="log.key || index" class="technical-event"><span>{{ log.title }}</span><small>{{ technicalLabel(log.status) }}</small><p v-if="log.summary && log.summary!==log.title">{{ log.summary }}</p></div></details>
      </section>
    </div>
    <footer class="inspector-footer"><span class="connection-dot" :class="{live:outcome.status==='running'}"></span>{{ outcome.status==='running'?'连接中 · 按真实执行事件更新':'本轮记录已收起为最终状态' }}<span v-if="workflow.run_id" class="run-reference">#{{ workflow.run_id.slice(-6) }}</span></footer>
  </aside>
</template>
<script setup>
import {computed,ref,watch,onMounted,onBeforeUnmount} from 'vue'
import {answerHtml} from '../../utils/answerPresentation'
import {buildResearchReportHtml} from '../../utils/researchReport'
import AnalysisBrief from './AnalysisBrief.vue'
import {latestAnalysisSummary} from '../../utils/analysisActivity'
import {taskOutcome,workflowStages,analysisPhases} from '../../state/askWorkflow'
const props=defineProps({logs:{type:Array,default:()=>[]},status:{type:String,default:'idle'},workflow:{type:Object,default:()=>({})},result:Object,busy:Boolean,allowTechnical:Boolean,allowRetry:Boolean,focusPhase:Number,allowReport:Boolean})
defineEmits(['close','retry','view-report'])
const tab=ref('progress'),follow=ref(true),selectedPhase=ref(0),selectedDataset=ref(0),selectedQueryLog=ref(0),clock=ref(Date.now())
let ticker
onMounted(()=>{ticker=setInterval(()=>{clock.value=Date.now()},1000)})
onBeforeUnmount(()=>clearInterval(ticker))
const outcome=computed(()=>taskOutcome(props.result,{status:props.status,busy:props.busy,workflow:props.workflow}))
const stageNodes=computed(()=>workflowStages(props.workflow,outcome.value.status))
const phases=computed(()=>analysisPhases(props.workflow,outcome.value.status))
const issues=computed(()=>stageNodes.value.filter(n=>['failed','warning','interrupted','retrying'].includes(n.status)))
const tabs=computed(()=>[{id:'progress',label:'进展'},...(props.allowReport && datasets.value.length?[{id:'report',label:'报告'}]:[]),...(props.allowTechnical?[{id:'queries',label:'查询依据'},{id:'diagnostics',label:'诊断'}]:[])])
const datasets=computed(()=>props.result?.research?(props.result.research.evidence || []).flatMap(e=>e.dataset_results || []):props.result?.dataset_results || [])
const reportHtml=computed(()=>props.result?.research?buildResearchReportHtml(props.result,{allowAutoChart:true}):answerHtml(props.result?.question,datasets.value,props.result?.analysis || props.result?.report || datasets.value.map(ds=>ds.analysis || '').join('\n\n')))
const hasRows=computed(()=>datasets.value.some(d=>Array.isArray(d.rows) && d.query_status!=='failed' && d.agent3_review?.approved!==false))
const rowCount=computed(()=>datasets.value.filter(d=>d.query_status!=='failed' && d.agent3_review?.approved!==false).reduce((n,d)=>n+(d.rows?.length || 0),0))
const currentDataset=computed(()=>datasets.value[selectedDataset.value])
const queryLogs=computed(()=>props.logs.filter(log=>log.sql || log.tableRows?.length))
const nodeLabel=status=>({planned:'未开始',unrecorded:'未单独记录',running:'进行中',retrying:'正在修复',completed:'已完成',warning:'需关注',failed:'未通过',interrupted:'未完成',waiting:'待确认',canceled:'已停止'}[status] || '未确认')
const nodeMark=status=>status==='completed'?'✓':['failed','warning','interrupted'].includes(status)?'!':status==='running'?'◌':'○'
const technicalLabel=status=>outcome.value.status!=='running' && ['running','pending'].includes(status)?'未完成':({success:'已记录',completed:'已记录',running:'进行中',error:'异常',warning:'需关注'}[status] || '已记录')
const elapsed=computed(()=>{
  const times=(props.workflow.events || []).map(e=>Date.parse(e.time)).filter(Number.isFinite)
  if(!times.length)return ''
  const end=outcome.value.status==='running'?clock.value:Math.max(...times)
  const seconds=Math.max(0,Math.floor((end-Math.min(...times))/1000))
  return seconds>=60?`${Math.floor(seconds/60)}分${seconds%60}秒`:`${seconds}秒`
})
function selectPhase(id){selectedPhase.value=id;follow.value=false}
watch(()=>props.workflow.run_id,()=>{tab.value='progress';follow.value=true;selectedPhase.value=0;selectedDataset.value=0;selectedQueryLog.value=0})
watch(()=>props.focusPhase,value=>{if(Number.isInteger(value)){tab.value='progress';selectPhase(value)}})
watch(()=>props.allowTechnical,value=>{if(!value)tab.value='progress'})
watch(()=>props.workflow.events?.at(-1)?.seq,()=>{if(follow.value){const active=phases.value.find(p=>p.status==='running');const latest=[...phases.value].reverse().find(p=>p.nodes.length);selectedPhase.value=(active || latest)?.id || 0}},{immediate:true})
watch(follow,value=>{if(value)selectedPhase.value=(phases.value.find(p=>p.status==='running') || [...phases.value].reverse().find(p=>p.nodes.length))?.id || 0})
</script>
<style scoped>
