spector-body{overflow-y:auto;min-height:0;flex:1;padding:20px 22px;overscroll-behavior:contain;scrollbar-gutter:stable}.section-caption{display:flex;justify-content:space-between;align-items:center;gap:10px;color:#66716b;font-size:12px;margin-bottom:16px}.section-caption button{font:inherit;font-size:11px;color:#66716b;background:none;border:0;cursor:pointer;padding:4px 0}.section-caption button[aria-pressed=true]{color:#386553}.phase-rail{list-style:none;margin:0;padding:0}.phase-rail>li{position:relative;padding:0 0 8px}.phase-rail>li:not(:last-child):before{content:'';position:absolute;left:22px;top:38px;bottom:0;width:1px;background:#e3e6e1}.phase-pick{position:relative;display:flex;align-items:center;gap:12px;padding:12px 10px;width:100%;text-align:left;background:transparent;border:1px solid transparent;border-radius:9px;font:inherit;cursor:pointer;color:#39463f}.selected .phase-pick{background:#f0f4ef;border-color:#dde8de}.phase-symbol{display:grid;place-items:center;width:25px;height:25px;border:1px solid #cbd5e1;background:white;border-radius:50%;font-size:11px;color:#64748b;flex-shrink:0}.completed .phase-symbol{background:#f0fdf4;border-color:#bbf7d0;color:#15803d}.running .phase-symbol{border-color:#9bb7a3;color:#386553;animation:beacon 1.7s ease infinite}.warning .phase-symbol{background:#fffbeb;color:#b45309;border-color:#fde68a}.phase-pick strong{display:block;font-size:13px;font-weight:550}.phase-pick small{display:block;color:#66716b;font-size:11px;margin-top:5px;line-height:1.6}.phase-chevron{margin-left:auto;color:#64748b}.phase-detail{border-top:1px solid #e3e6e1;padding-top:18px;margin-top:16px}.detail-heading{display:flex;justify-content:space-between;gap:12px;align-items:center}.detail-heading h4{font-size:14px;margin:0}.detail-heading>span{font-size:11px;color:#66716b}.phase-detail>p,.query-evidence>p{font-size:12px;color:#66716b;line-height:1.8}.step-detail{border-bottom:1px solid #edf2f7;padding:12px 0}.step-detail summary{display:flex;gap: