ap:10px;flex-wrap:wrap;border-bottom:1px solid #e3e6e1;padding:12px 0}.technical-event>span{font-weight:500;color:#39463f}.technical-event small{color:#66716b}.technical-event p{flex-basis:100%;margin:0;color:#66716b;overflow-wrap:anywhere}.inspector-footer{display:flex;align-items:center;gap:7px;padding:12px 18px;border-top:1px solid #e3e6e1;color:#66716b;font-size:11px;background:#f7f7f5}.connection-dot.live{background:#386553}.run-reference{margin-left:auto;font-family:var(--font-mono,monospace)}button:focus-visible,summary:focus-visible,select:focus-visible{outline:2px solid #386553;outline-offset:3px}@keyframes beacon{50%{opacity:.5}}@media(prefers-reduced-motion:reduce){*{animation:none!important}}@media(max-width:600px){.inspector-header{padding:16px 18px 12px}.inspector-body{padding:16px 18px}.mission-status{margin:0 14px 14px}.inspector-tabs{padding:0 18px}}

.reasoning-panel{color:#24292e;border-color:#e3e6e1}.inspector-header{padding:22px 24px 18px}.inspector-kicker{color:#66716b;font-size:10px;letter-spacing:1px}.inspector-header h3{font-size:18px;letter-spacing:-.3px;margin-top:6px}.icon-button{background:#f1f3ee;color:#66716b;border-radius:50%;width:28px;height:28px;font-size:21px}.mission-status{margin:0 20px 18px;padding:14px 16px;border:1px solid #e3e6e1;background:#f7f8f4;border-radius:10px}.mission-label strong{font-size:13px}.mission-label time{font-size:11px}.mission-status p{font-size:12px;color:#48534d;line-height:1.8}.mission-facts{font-size:11px;color:#66716b}.running .status-beacon{background:#386553;box-shadow:0 0 0 3px #e3ecdf}.inspector-tabs{padding:0 24px;gap:24px;border-color:#e3e6e1}.inspector-tabs button{font-size:12px;color:#66716b;padding-bottom:12px}.inspector-tabs button[aria-pressed=true]{color:#294e3e;border-color:#386553}.inspector-body{padding:22px 24px}.phase-pick{border-radius:7px;padding:11px 8px;color:#48534d}.selected .phase-pick{background:#f0f4ec;border-color:#e0e7da}.phase-symbol{border-radius:6px;border-color:#d5ddd2;color:#66716b}.phase-pick strong{font-size:12px}.phase-pick small{color:#66716b}.phase-chevron{color:#889186}.section-caption{font-size:12px}.section-caption button{font-size:11px}.inspector-footer{background:#fafbf8;border-color:#e3e6e1;color:#66716b;font-size:10px;padding:12px 20px}.inspector-sql{background:#252d29;color:#e1e8de}.phase-detail{border-color:#e3e6e1}.connection-dot.live{background:#386553}.report-preview iframe{border-color:#e3e6e1}
</style>

<style scoped>.report-preview iframe{display:block;width:100%;height:720px;border:1px solid #e3e6e1;border-radius:8px;background:white}.report-preview .section-caption button{color:#386553}@media(max-width:600px){.report-preview iframe{height:65dvh}}</style>
